import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Instant Answers & Keyword Features","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Always Active Instant Answers","slug":"_1-always-active-instant-answers","link":"#_1-always-active-instant-answers","children":[{"level":3,"title":"Calculator & Base Conversion","slug":"calculator-base-conversion","link":"#calculator-base-conversion","children":[]},{"level":3,"title":"Environment Variable Expansion & Inspection","slug":"environment-variable-expansion-inspection","link":"#environment-variable-expansion-inspection","children":[]},{"level":3,"title":"Quick Command Execution","slug":"quick-command-execution","link":"#quick-command-execution","children":[]},{"level":3,"title":"Direct URL Navigation","slug":"direct-url-navigation","link":"#direct-url-navigation","children":[]},{"level":3,"title":"Clipboard text in the Quick Search Window","slug":"clipboard-text-in-the-quick-search-window","link":"#clipboard-text-in-the-quick-search-window","children":[]}]},{"level":2,"title":"2. Keyword-Triggered Plugin Extensions","slug":"_2-keyword-triggered-plugin-extensions","link":"#_2-keyword-triggered-plugin-extensions","children":[]},{"level":2,"title":"3. Web Search Engines","slug":"_3-web-search-engines","link":"#_3-web-search-engines","children":[]},{"level":2,"title":"4. Instant Translation","slug":"_4-instant-translation","link":"#_4-instant-translation","children":[]},{"level":2,"title":"5. File Filters","slug":"_5-file-filters","link":"#_5-file-filters","children":[]},{"level":2,"title":"6. Custom Commands","slug":"_6-custom-commands","link":"#_6-custom-commands","children":[]}],"relativePath":"user-guide/instant-answers.md","filePath":"user-guide/instant-answers.md","lastUpdated":1791259152000}`),a={name:`user-guide/instant-answers.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="instant-answers-keyword-features" tabindex="-1">Instant Answers &amp; Keyword Features <a class="header-anchor" href="#instant-answers-keyword-features" aria-label="Permalink to “Instant Answers &amp; Keyword Features”">​</a></h1><p>Beyond local file search, Lertaro includes a suite of instant calculations, system tools, and keyword-triggered plugin extensions. Answers appear immediately without waiting for file search results.</p><h2 id="_1-always-active-instant-answers" tabindex="-1">1. Always Active Instant Answers <a class="header-anchor" href="#_1-always-active-instant-answers" aria-label="Permalink to “1. Always Active Instant Answers”">​</a></h2><p>These features do not require any trigger prefix; they activate automatically whenever the input matches their patterns:</p><h3 id="calculator-base-conversion" tabindex="-1">Calculator &amp; Base Conversion <a class="header-anchor" href="#calculator-base-conversion" aria-label="Permalink to “Calculator &amp; Base Conversion”">​</a></h3><p>Type any arithmetic expression directly into the search bar. Results appear in real time. Press <code>Enter</code> to copy the evaluated result to the clipboard:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>Common number base conversions are supported out of the box:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="environment-variable-expansion-inspection" tabindex="-1">Environment Variable Expansion &amp; Inspection <a class="header-anchor" href="#environment-variable-expansion-inspection" aria-label="Permalink to “Environment Variable Expansion &amp; Inspection”">​</a></h3><ul><li><strong>Expand Variables</strong>: Type <code>%NAME%</code> (e.g. <code>%PATH%</code>, <code>%APPDATA%</code>) to inspect its evaluated value. Multi-path variables such as <code>PATH</code> are split into clear line-by-line lists for inspection.</li><li><strong>Fuzzy Search Variables</strong>: Type <code>%</code> followed by a keyword (e.g. <code>%temp</code>) to fuzzy-search across all system and user environment variables.</li></ul><h3 id="quick-command-execution" tabindex="-1">Quick Command Execution <a class="header-anchor" href="#quick-command-execution" aria-label="Permalink to “Quick Command Execution”">​</a></h3><p>Run commands directly without launching a terminal window first:</p><ul><li><code>#&lt;command&gt;</code>: Opens a command prompt and executes the command <strong>with Administrator privileges</strong> (e.g. <code>#sfc /scannow</code> or <code>#net start LertaroService</code>).</li><li><code>$&lt;command&gt;</code>: Opens a command prompt and executes the command with <strong>standard user permissions</strong> (e.g. <code>$ping 1.1.1.1</code> or <code>$ipconfig /all</code>).</li></ul><p>Under <strong>Settings → Plugins → Core Extensions → Configure → Command Executor</strong>, choose CMD (default), Windows PowerShell, or PowerShell (pwsh). <strong>Run in current directory</strong> uses the inline window&#39;s directory or the last browsed directory for quick search. If no directory has been obtained (for example, when first using quick search), it uses your user profile directory. An unavailable chosen directory stops execution.</p><p>Enable <strong>Show in cascading folder browser</strong> to add <strong>Run command in this directory</strong>. Its prompt lets you choose an interpreter and elevation for each command, always using the menu&#39;s source directory; a child folder&#39;s context menu uses that folder. Empty input opens the selected shell, and <code>#</code>/<code>$</code> overrides the elevation checkbox. Exact <code>cmd</code>, <code>powershell</code>, or <code>pwsh</code> after the prefix (case-insensitive, trimming whitespace) opens that program directly; only a missing executable falls back to CMD with the original input. A missing interpreter selected for an ordinary command reports an error without changing script syntax.</p><p>CMD expands <code>%CD%</code> in a startup command before changing directory. If elevation or a UNC path makes Windows override the initial directory, that variable may still refer to the old directory. Choose PowerShell and use <code>$PWD</code> when a startup command needs to read the directory.</p><h3 id="direct-url-navigation" tabindex="-1">Direct URL Navigation <a class="header-anchor" href="#direct-url-navigation" aria-label="Permalink to “Direct URL Navigation”">​</a></h3><p>Type or paste any URL beginning with <code>http://</code> or <code>https://</code> and press <code>Enter</code> to open it immediately in your default browser. Entering a valid protocol-less web address such as <code>example.com</code> generates two instant results in the Quick Search Window: <code>https://...</code> and <code>http://...</code>. The protocol-less guess only applies to a hard-coded whitelist of common top-level domains (over a hundred suffixes such as <code>.com</code>, <code>.cn</code>, and <code>.io</code>, plus <code>xn--</code> internationalized domains) and is not configurable; suffixes that double as common file extensions are deliberately left out, and anything else stays a file search, so <code>abc.txt</code> produces no browser row. Add the protocol yourself to open a URL the list does not cover. Each result uses the two-line browser-open presentation, the query text is not modified, and an address that already includes a protocol produces one result.</p><h3 id="clipboard-text-in-the-quick-search-window" tabindex="-1">Clipboard text in the Quick Search Window <a class="header-anchor" href="#clipboard-text-in-the-quick-search-window" aria-label="Permalink to “Clipboard text in the Quick Search Window”">​</a></h3><p>With <strong>Settings → General → Quick Search Window → Auto-fill Quick Search box from clipboard</strong> enabled (off by default), when the Quick Search Window is summoned without prefilled text, a non-empty clipboard text is imported and selected automatically if it differs from the last clipboard value imported by that window. The same value is not imported repeatedly, and prefilled queries from a URI or from returning from the full search window are never overwritten.</p><h2 id="_2-keyword-triggered-plugin-extensions" tabindex="-1">2. Keyword-Triggered Plugin Extensions <a class="header-anchor" href="#_2-keyword-triggered-plugin-extensions" aria-label="Permalink to “2. Keyword-Triggered Plugin Extensions”">​</a></h2><p>By typing a short <strong>trigger keyword + space</strong> followed by your query, you can invoke dedicated plugin capabilities. All keywords can be customized under <a href="./settings/plugins.html"><strong>Settings → Plugins</strong></a>.</p><p>A half-width space, a full-width space or a tab all separate the keyword from what follows, and the keyword itself never takes part in file-name matching or highlighting. If two features answer to the same keyword, the plugin&#39;s configuration page flags it in amber under that field and names the other one -- saving is not blocked.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Default Keyword</th><th style="text-align:left;">Plugin Name</th><th style="text-align:left;">Description &amp; Use Case</th><th style="text-align:left;">Example Usage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>Process Manager</strong></td><td style="text-align:left;">Search running processes by name, PID, or window title (supports pinyin). Press Enter to terminate.</td><td style="text-align:left;"><code>ps chrome</code> or <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>Window Switcher</strong></td><td style="text-align:left;">Search and jump to active application windows with live background thumbnail snapshots.</td><td style="text-align:left;"><code>win code</code> or <code>win browser</code></td></tr><tr><td style="text-align:left;"><code>bb</code></td><td style="text-align:left;"><strong>Browser Bookmarks</strong></td><td style="text-align:left;">Search bookmarks from Chrome, Edge, and Firefox profiles.</td><td style="text-align:left;"><code>bb github</code></td></tr><tr><td style="text-align:left;"><code>bh</code></td><td style="text-align:left;"><strong>Browser History</strong></td><td style="text-align:left;">Search browsing history from Chrome, Edge, and Firefox profiles.</td><td style="text-align:left;"><code>bh github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>Settings Search</strong></td><td style="text-align:left;">Fuzzy-search Lertaro&#39;s internal settings. Selecting an item jumps directly to that setting page and highlights it.</td><td style="text-align:left;"><code>set hotkey</code> or <code>set fuzzy</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow Launcher Bridge</strong></td><td style="text-align:left;">Lists loaded Flow.Launcher plugins and their action keywords, connecting with the Flow community ecosystem.</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>Content Search</strong></td><td style="text-align:left;">Searches the text of indexed local documents and returns matching files with snippets.</td><td style="text-align:left;"><code>cs project plan</code></td></tr></tbody></table><h2 id="_3-web-search-engines" tabindex="-1">3. Web Search Engines <a class="header-anchor" href="#_3-web-search-engines" aria-label="Permalink to “3. Web Search Engines”">​</a></h2><p>The Web Search plugin provides built-in shortcuts for major search engines. Type the prefix followed by your query to search in your default browser:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Shortcut</th><th style="text-align:left;">Search Engine</th><th style="text-align:left;">Example</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">Baidu</td><td style="text-align:left;"><code>bd deep learning</code></td><td style="text-align:left;">Search via Baidu</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">Google</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">Search via Google</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">Bing</td><td style="text-align:left;"><code>bing microsoft docs</code></td><td style="text-align:left;">Search via Bing</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">Search directly across GitHub repositories</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">Wikipedia</td><td style="text-align:left;"><code>wiki quantum computing</code></td><td style="text-align:left;">Look up Wikipedia entries</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">Search YouTube videos</td></tr></tbody></table><p>You can add, edit, or remove search engines and custom URL templates under <strong>Settings → Plugins → Web Search → Configure</strong>.</p><h2 id="_4-instant-translation" tabindex="-1">4. Instant Translation <a class="header-anchor" href="#_4-instant-translation" aria-label="Permalink to “4. Instant Translation”">​</a></h2><p>Type the default trigger <code>tr</code> followed by text to translate it automatically into the language currently selected in Lertaro&#39;s interface:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>Results appear asynchronously as you type; press <code>Enter</code> to copy the translation.</li><li>Customize the trigger keyword under <strong>Settings → Plugins → Translator → Configure</strong>.</li></ul><h2 id="_5-file-filters" tabindex="-1">5. File Filters <a class="header-anchor" href="#_5-file-filters" aria-label="Permalink to “5. File Filters”">​</a></h2><p>Under <strong>Settings → Plugins → File Filters → Configure</strong>, you can bind a trigger keyword to specific folders so a normal search can be scoped to them:</p><ul><li><strong>Target Folders</strong>: One path per line (e.g. <code>D:\\Engineering\\Drawings</code>); environment variables (e.g. <code>%TEMP%</code>) and shell virtual paths (e.g. <code>shell:Downloads</code>) are also accepted, and an entry that resolves to nothing is skipped. Results come from the file index, so folders should be index-covered (an enabled local drive, or added under <strong>Settings → Index → Folders</strong>, which also accepts network shares); an uncovered folder is skipped with a warning in the log.</li><li><strong>Matching Rules</strong>: File name patterns such as <code>*.dwg;*.dxf</code> (folders always included).</li><li><strong>Trigger Keyword</strong>: Bind a prefix (e.g. <code>cad</code>), then typing <code>cad bracket_assembly</code> in the quick search window runs the normal index search -- filename fuzzy matching, pinyin aliases included -- restricted to the bound folders. Typing the keyword alone asks you to keep typing.</li></ul><h2 id="_6-custom-commands" tabindex="-1">6. Custom Commands <a class="header-anchor" href="#_6-custom-commands" aria-label="Permalink to “6. Custom Commands”">​</a></h2><p>Under <strong>Settings → Plugins → Custom Commands → Configure</strong>, wrap complex scripts, tools, or applications into concise commands:</p><ul><li><strong>Parameter Placeholders</strong>: Supports positional placeholders <code>%s1</code>, <code>%s2</code>... and full query capture <code>%s</code>.</li><li><strong>Run in current directory</strong>: Overrides the fixed working directory with the cascading menu&#39;s source directory, the inline window&#39;s directory, or the last browsed directory for quick search. An unavailable directory stops execution. Disabled by default to preserve existing configurations.</li><li><strong>Quick Navigation Integration</strong>: Check &quot;Show in Quick Navigation&quot; to pin the command directly into the <a href="./hotkeys.html#_3-quick-navigation-mouse-triggers"><strong>Quick Navigation</strong></a> menu, with optional <code>/</code> submenu paths (e.g. <code>DevTools/RestartService</code>).</li></ul>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};